import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1795196707000}'),n={name:"guide/getting-started.md"};function o(d,e,l,r,p,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide walks through building <code>jetpack-daemon</code>, inspecting your host hardware profile, starting the background tray daemon, and opening the embedded <strong>Control Center</strong> at <code>http://127.0.0.1:9470</code>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><strong>Rust 1.75+</strong> (stable toolchain) with the WebAssembly target:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wasm32-unknown-unknown</span></span></code></pre></div></li><li><strong>Node.js 20+</strong> and <code>npm</code> (for building the WASM bindings and Control Center UI, or running the documentation portal).</li><li><strong>Platform notes</strong>: <ul><li><strong>Windows (<code>windows/amd64</code>)</strong>: Standard user account; no Administrator / UAC elevation required.</li><li><strong>macOS (<code>darwin/arm64</code>)</strong>: Apple Silicon with Xcode Command Line Tools (<code>Metal.framework</code> is detected automatically).</li><li><strong>Linux (<code>linux/amd64</code>)</strong>: <code>bubblewrap</code> (<code>bwrap</code>) installed with unprivileged user namespaces enabled, plus a kernel supporting Landlock LSM (<code>Linux 5.13+</code>).</li></ul></li></ul><h2 id="_1-build-the-daemon-and-embedded-control-center" tabindex="-1">1. Build the Daemon and Embedded Control Center <a class="header-anchor" href="#_1-build-the-daemon-and-embedded-control-center" aria-label="Permalink to &quot;1. Build the Daemon and Embedded Control Center&quot;">​</a></h2><p>Build the WASM client, compile the Control Center frontend (<code>web/dist/</code>), and produce the single <code>jetpack-daemon</code> release binary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release-daemon</span></span></code></pre></div><p>Or run the debug workspace build during development:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span></span></code></pre></div><h2 id="_2-verify-host-hardware-discovery" tabindex="-1">2. Verify Host Hardware Discovery <a class="header-anchor" href="#_2-verify-host-hardware-discovery" aria-label="Permalink to &quot;2. Verify Host Hardware Discovery&quot;">​</a></h2><p>Probe your CPU topology, system/unified memory, and GPU adapters (<code>NVML</code> / <code>Vulkan</code> / <code>DX12</code> / <code>Metal</code>) directly in user space:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/debug/jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print-hardware-profile</span></span></code></pre></div><p>Example output on Apple Silicon:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JetPack Hardware Profile (macos/aarch64)</span></span>
<span class="line"><span>  CPU:    Apple M1 Pro (10 physical / 10 logical cores, 8P + 2E)</span></span>
<span class="line"><span>  Memory: 16384 MiB total / 3241 MiB available (unified=true, recommended_max_working_set=12124 MiB)</span></span>
<span class="line"><span>  GPUs (1 detected):</span></span>
<span class="line"><span>    [0] Apple M1 Pro | vendor=Apple | backend=Metal | driver=Metal | vram=12124 MiB total (3241 MiB free) | unified=true</span></span></code></pre></div><h2 id="_3-start-the-daemon-and-open-control-center" tabindex="-1">3. Start the Daemon and Open Control Center <a class="header-anchor" href="#_3-start-the-daemon-and-open-control-center" aria-label="Permalink to &quot;3. Start the Daemon and Open Control Center&quot;">​</a></h2><p>Launch <code>jetpack-daemon</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUST_LOG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./target/release/jetpack-daemon</span></span></code></pre></div><p><em>(For headless CI or SSH environments without a desktop system tray, pass <code>--headless</code>.)</em></p><p>When started:</p><ol><li><code>JetPackPaths::init_dirs()</code> initializes your isolated user-space directory (<code>0700</code> on Unix).</li><li><code>jetpack-daemon</code> registers the <code>jetpack://</code> custom URI scheme in user space (<code>HKCU\\Software\\Classes</code> on Windows, <code>~/.local/share/applications/jetpack-daemon.desktop</code> on Linux, bundle <code>Info.plist</code> on macOS).</li><li>The system tray icon appears in the OS menu bar / notification area with quick status and shortcuts.</li><li>The loopback gatekeeper and embedded Control Center start listening strictly on <code>127.0.0.1:9470</code>.</li></ol><p>Open the Control Center in your browser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:9470</span></span></code></pre></div><p>From the Control Center you can:</p><ul><li>Inspect live CPU, RAM, and GPU telemetry (<code>hardware.get_profile</code>).</li><li>Browse and install verified applications from the <code>Ed25519</code>-signed <strong>App Store</strong> (<code>SignedAppCatalog</code>). Official release installers pre-bundle only the slimmed <code>examples/ffmpeg-media-converter</code> starter worker (<code>io.jetpack.media-converter</code>) to minimize installer size, while other services are downloaded on demand from the catalog.</li><li>Launch or terminate installed apps, reset cached volume folder authorizations, and monitor local developer apps (<code>UNVERIFIED / LOCAL DEV</code>).</li><li>Review and revoke paired browser origins (<code>paired_clients.db</code>).</li><li>Export a secret-redacted <code>.zip</code> diagnostic bundle (<code>diagnostics.json</code> + bounded <code>daemon.log</code> tail) from <strong>My Hardware &amp; Security -&gt; Diagnostics &amp; Support Logs</strong>, the system tray (<strong>&quot;Export Diagnostics...&quot;</strong>), or CLI (<code>jetpack-daemon --export-diagnostics</code>). Optional HTTP JSON reporting is disabled by default (<code>[diagnostics].report_url = None</code> in <code>daemon.toml</code>) and enforces <code>https://</code> (or loopback <code>http://</code> for local testing) with bounded <code>request_timeout_secs</code> (<code>1..=60</code>).</li></ul><h2 id="_4-run-built-in-verification-smoke-tests" tabindex="-1">4. Run Built-In Verification Smoke Tests <a class="header-anchor" href="#_4-run-built-in-verification-smoke-tests" aria-label="Permalink to &quot;4. Run Built-In Verification Smoke Tests&quot;">​</a></h2><p>Before connecting an external web app or publishing workers, you can verify the entire local security stack offline:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Verify 127.0.0.1 binding, PNA headers, X25519/Ed25519 handshake, ChaCha20-Poly1305 &amp; 1003 JSON rejection</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/debug/jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ws-smoke-test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Verify OCI multi-arch CAS &amp; hardlink/APFS clone deduplication</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/debug/jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oci-smoke-test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Verify isolated uv + python-build-standalone provisioner</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/debug/jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --python-smoke-test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Verify OS native kernel sandbox (AppContainer / Seatbelt / bwrap+Landlock)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/debug/jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sandbox-smoke-test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Verify sandboxed worker IPC, userspace network proxy &amp; lifecycle cleanup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/debug/jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --worker-ipc-smoke-test</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Connect a web app using the <a href="/sdk/frontend/quickstart">@jetpack/client Quickstart</a>.</li><li>Scaffold your first Python worker with <code>--init-app</code> in the <a href="/publishing/cli-tools">CLI Tools Reference</a>.</li><li>Inspect the cryptographic and sandbox guarantees in <a href="/security/overview">Security Overview</a>.</li></ul>`,29)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
